'use client';

import React, { useState, useEffect } from 'react';
import { Task, TaskCreateRequest, TaskUpdateRequest } from '@/types';
import { taskService } from '@/services/task';
import { useAuth } from '@/components/AuthContext';
import { 
  Plus, Search, Filter, SortAsc, Calendar, 
  CheckCircle, Circle, Trash2, Edit2, X, Tag, AlertCircle, Loader2 
} from 'lucide-react';

interface TodoListProps {
  onTaskUpdated?: () => void;
}

const TodoList: React.FC<TodoListProps> = ({ onTaskUpdated }) => {
  // --- STATE MANAGEMENT ---
  const [tasks, setTasks] = useState<Task[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  
  // Create State
  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [newTaskDescription, setNewTaskDescription] = useState('');
  const [newTaskPriority, setNewTaskPriority] = useState<'High' | 'Medium' | 'Low'>('Medium');
  const [newTaskTags, setNewTaskTags] = useState('');
  
  // Edit State
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [editDescription, setEditDescription] = useState('');
  const [editPriority, setEditPriority] = useState<'High' | 'Medium' | 'Low'>('Medium');
  const [editTags, setEditTags] = useState('');
  
  // Filter/Sort State
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState<'all' | 'active' | 'completed'>('all');
  const [filterPriority, setFilterPriority] = useState<'all' | 'High' | 'Medium' | 'Low'>('all');
  const [sortBy, setSortBy] = useState<'created_at' | 'priority' | 'title'>('created_at');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');
  
  const [showAddForm, setShowAddForm] = useState(false);
  const { user } = useAuth();

  // --- EFFECTS ---
  useEffect(() => {
    fetchTasks();
  }, [user]);

  useEffect(() => {
    if (onTaskUpdated) onTaskUpdated();
  }, [tasks, onTaskUpdated]);

  // --- API HANDLERS ---
  const fetchTasks = async () => {
    const token = localStorage.getItem('token');
    if (!user || !token) {
      setLoading(false);
      return;
    }

    try {
      setLoading(true);
      const response = await taskService.getTasks();
      if (response.success && response.data) {
        setTasks(response.data);
      } else {
        setError(response.error || 'Failed to fetch tasks');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error fetching tasks');
    } finally {
      setLoading(false);
    }
  };

  const handleCreateTask = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTaskTitle.trim()) return;

    const tags = newTaskTags.split(',').map(tag => tag.trim()).filter(tag => tag);
    const taskData: TaskCreateRequest = {
      title: newTaskTitle,
      description: newTaskDescription,
      priority: newTaskPriority,
      tags: tags,
    };

    try {
      const response = await taskService.createTask(taskData);
      if (response.success && response.data) {
        setTasks([response.data, ...tasks]);
        setNewTaskTitle('');
        setNewTaskDescription('');
        setNewTaskPriority('Medium');
        setNewTaskTags('');
        setShowAddForm(false);
        setError(null);
      } else {
        setError(response.error || 'Failed to create task');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    }
  };

  const handleUpdateTask = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingTask) return;

    const tags = editTags.split(',').map(tag => tag.trim()).filter(tag => tag);
    const taskData: TaskUpdateRequest = {
      title: editTitle,
      description: editDescription,
      priority: editPriority,
      tags: tags,
    };

    try {
      const response = await taskService.updateTask(editingTask.id, taskData);
      if (response.success && response.data) {
        setTasks(tasks.map(task => task.id === editingTask.id ? response.data! : task));
        setEditingTask(null);
        setError(null);
      } else {
        setError(response.error || 'Failed to update task');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    }
  };

  const handleDeleteTask = async (id: number) => {
    if(!confirm('Are you sure you want to delete this task?')) return;
    try {
      const response = await taskService.deleteTask(id);
      if (response.success) {
        setTasks(tasks.filter(task => task.id !== id));
      } else {
        setError(response.error || 'Failed to delete task');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    }
  };

  const handleToggleCompletion = async (id: number) => {
    try {
      const response = await taskService.toggleTaskCompletion(id);
      if (response.success && response.data) {
        setTasks(tasks.map(task => task.id === id ? response.data! : task));
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    }
  };

  const startEditing = (task: Task) => {
    setEditingTask(task);
    setEditTitle(task.title);
    setEditDescription(task.description || '');
    setEditPriority(task.priority);
    setEditTags(task.tags.join(', '));
    setShowAddForm(false); // Close add form if open
  };

  // --- FILTERING LOGIC ---
  const filteredTasks = tasks
    .filter(task => {
      const matchesSearch = task.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                            (task.description && task.description.toLowerCase().includes(searchTerm.toLowerCase()));
      const matchesStatus = filterStatus === 'all' ||
                            (filterStatus === 'active' && !task.completed) ||
                            (filterStatus === 'completed' && task.completed);
      const matchesPriority = filterPriority === 'all' || task.priority === filterPriority;
      return matchesSearch && matchesStatus && matchesPriority;
    })
    .sort((a, b) => {
      let comparison = 0;
      switch (sortBy) {
        case 'title': comparison = a.title.localeCompare(b.title); break;
        case 'priority': 
          const pOrder = { 'High': 3, 'Medium': 2, 'Low': 1 };
          comparison = pOrder[b.priority] - pOrder[a.priority]; 
          break;
        case 'created_at': comparison = new Date(a.created_at).getTime() - new Date(b.created_at).getTime(); break;
      }
      return sortOrder === 'asc' ? comparison : -comparison;
    });

  if (loading && tasks.length === 0) {
    return (
      <div className="flex justify-center items-center h-64">
        <Loader2 className="animate-spin h-10 w-10 text-indigo-500" />
      </div>
    );
  }

  // --- RENDER HELPERS ---
  const InputClasses = "w-full px-4 py-3 bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl text-gray-900 dark:text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-colors";
  const SelectClasses = "appearance-none w-full sm:w-auto px-4 pr-10 py-2.5 text-center bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl text-gray-700 dark:text-gray-200 focus:outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer font-medium transition-all shadow-sm";

  return (
    <div className="w-full">
      {error && (
        <div className="bg-red-500/10 border border-red-500/20 text-red-600 dark:text-red-400 px-4 py-3 rounded-xl mb-6 flex items-center gap-2">
          <AlertCircle className="w-5 h-5" />
          {error}
        </div>
      )}

      {/* --- CONTROLS BAR --- */}
      <div className="mb-8 p-4 bg-white/50 dark:bg-gray-800/40 backdrop-blur-md border border-white/50 dark:border-gray-700/50 rounded-2xl shadow-sm">
        <div className="flex flex-col lg:flex-row gap-4 justify-between">
          
          {/* Add Button & Search */}
          <div className="flex flex-col sm:flex-row gap-4 flex-1">
            <button
              onClick={() => {
                setShowAddForm(!showAddForm);
                setEditingTask(null);
              }}
              className={`flex items-center justify-center gap-2 px-6 py-2.5 font-bold rounded-xl transition-all shadow-md 
                ${showAddForm 
                  ? 'bg-gray-200 text-gray-700 dark:bg-gray-700 dark:text-gray-200 hover:bg-gray-300' 
                  : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-indigo-500/30'}`}
            >
              {showAddForm ? <X className="w-5 h-5" /> : <Plus className="w-5 h-5" />}
              {showAddForm ? 'Cancel' : 'New Task'}
            </button>

            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
              <input
                type="text"
                placeholder="Search tasks..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl text-gray-900 dark:text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
            </div>
          </div>

          {/* Filters & Sorts */}
          
        </div>
      </div>

      {/* --- CREATE / EDIT FORM --- */}
      {(showAddForm || editingTask) && (
        <div className="mb-8 p-6 bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-2xl shadow-xl animate-in fade-in slide-in-from-top-4 duration-300">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
              {editingTask ? <Edit2 className="w-5 h-5 text-indigo-500" /> : <Plus className="w-5 h-5 text-indigo-500" />}
              {editingTask ? 'Edit Task' : 'Create New Task'}
            </h3>
            <button onClick={() => { setShowAddForm(false); setEditingTask(null); }} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200">
              <X className="w-6 h-6" />
            </button>
          </div>

          <form onSubmit={editingTask ? handleUpdateTask : handleCreateTask}>
            <div className="space-y-4">
              <div>
                <input
                  type="text"
                  placeholder="Task Title"
                  value={editingTask ? editTitle : newTaskTitle}
                  onChange={(e) => editingTask ? setEditTitle(e.target.value) : setNewTaskTitle(e.target.value)}
                  className={InputClasses}
                  required
                />
              </div>

              <div>
                <textarea
                  placeholder="Description (Optional)"
                  value={editingTask ? editDescription : newTaskDescription}
                  onChange={(e) => editingTask ? setEditDescription(e.target.value) : setNewTaskDescription(e.target.value)}
                  className={InputClasses}
                  rows={3}
                />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                   <label className="block text-xs font-semibold text-gray-500 dark:text-gray-400 mb-2 uppercase tracking-wider">Priority</label>
                   <select
                     value={editingTask ? editPriority : newTaskPriority}
                     onChange={(e) => editingTask ? setEditPriority(e.target.value as any) : setNewTaskPriority(e.target.value as any)}
                     className={InputClasses}
                   >
                     <option value="High">High Priority</option>
                     <option value="Medium">Medium Priority</option>
                     <option value="Low">Low Priority</option>
                   </select>
                </div>

                <div>
                  <label className="block text-xs font-semibold text-gray-500 dark:text-gray-400 mb-2 uppercase tracking-wider">Tags</label>
                  <input
                    type="text"
                    placeholder="Comma separated (e.g. Work, Urgent)"
                    value={editingTask ? editTags : newTaskTags}
                    onChange={(e) => editingTask ? setEditTags(e.target.value) : setNewTaskTags(e.target.value)}
                    className={InputClasses}
                  />
                </div>
              </div>

              <div className="pt-4 flex gap-3 justify-end">
                <button
                  type="button"
                  onClick={() => { setShowAddForm(false); setEditingTask(null); }}
                  className="px-6 py-3 rounded-xl font-medium text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-8 py-3 bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white font-bold rounded-xl shadow-lg shadow-indigo-500/30 transition-all hover:scale-[1.02]"
                >
                  {editingTask ? 'Save Changes' : 'Create Task'}
                </button>
              </div>
            </div>
          </form>
        </div>
      )}

      {/* --- TASK LIST RENDER --- */}
      <div className="space-y-4">
        {filteredTasks.length === 0 ? (
          <div className="text-center py-16 bg-white/30 dark:bg-gray-800/20 rounded-3xl border border-dashed border-gray-300 dark:border-gray-700">
            <div className="inline-block p-4 rounded-full bg-gray-100 dark:bg-gray-800 mb-4">
              <Calendar className="w-10 h-10 text-gray-400 dark:text-gray-500" />
            </div>
            <h3 className="text-lg font-bold text-gray-900 dark:text-white">No tasks found</h3>
            <p className="text-gray-500 dark:text-gray-400 mt-1">Try adjusting your filters or add a new task.</p>
          </div>
        ) : (
          filteredTasks.map(task => (
            <div
              key={task.id}
              className={`group flex flex-col sm:flex-row items-start sm:items-center justify-between p-5 rounded-2xl transition-all duration-300 border
                ${task.completed
                  ? 'bg-gray-50/80 dark:bg-gray-900/40 border-gray-200 dark:border-gray-800' // Completed State
                  : 'bg-white dark:bg-gray-800/40 border-white/50 dark:border-gray-700/50 hover:shadow-lg hover:border-indigo-300 dark:hover:border-indigo-500/50' // Active State
                }
              `}
            >
              <div className="flex items-start gap-4 flex-1 w-full">
                {/* Completion Toggle */}
                <button
                  onClick={() => handleToggleCompletion(task.id)}
                  className={`mt-1 sm:mt-0 shrink-0 transition-colors duration-300 ${task.completed ? 'text-green-500' : 'text-gray-300 dark:text-gray-500 hover:text-indigo-500'}`}
                >
                  {task.completed ? <CheckCircle className="w-6 h-6 fill-current/10" /> : <Circle className="w-6 h-6" />}
                </button>
                
                <div className="flex-1 min-w-0">
                  <div className="flex flex-wrap items-center gap-2 mb-1">
                    <h3 className={`text-lg font-semibold truncate transition-all duration-300 ${
                        task.completed ? 'text-gray-400 dark:text-gray-600 line-through' : 'text-gray-800 dark:text-white'
                      }`}
                    >
                      {task.title}
                    </h3>
                    
                    {/* Priority Badge */}
                    <span className={`px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider rounded-full border ${
                        task.priority === 'High' ? 'bg-red-100 text-red-700 border-red-200 dark:bg-red-900/30 dark:text-red-300 dark:border-red-800' :
                        task.priority === 'Medium' ? 'bg-yellow-100 text-yellow-700 border-yellow-200 dark:bg-yellow-900/30 dark:text-yellow-300 dark:border-yellow-800' :
                        'bg-green-100 text-green-700 border-green-200 dark:bg-green-900/30 dark:text-green-300 dark:border-green-800'
                      }`}
                    >
                      {task.priority}
                    </span>
                  </div>

                  {task.description && (
                    <p className={`text-sm mb-2 line-clamp-2 ${task.completed ? 'text-gray-400 dark:text-gray-600' : 'text-gray-600 dark:text-gray-400'}`}>
                      {task.description}
                    </p>
                  )}

                  {/* Metadata Row */}
                  <div className="flex flex-wrap items-center gap-3 text-xs text-gray-400 dark:text-gray-500">
                    <span className="flex items-center gap-1 bg-gray-100 dark:bg-gray-800 px-2 py-1 rounded-md">
                      <Calendar className="w-3 h-3" />
                      {new Date(task.created_at).toLocaleDateString()}
                    </span>
                    
                    {task.tags && task.tags.length > 0 && (
                      <div className="flex items-center gap-2">
                        {task.tags.map((tag, idx) => (
                           <span key={idx} className="flex items-center gap-1 text-indigo-500 dark:text-indigo-400">
                             <Tag className="w-3 h-3" /> {tag}
                           </span>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              </div>

              {/* Action Buttons */}
              <div className="flex gap-1 mt-4 sm:mt-0 sm:ml-4 w-full sm:w-auto justify-end">
                <button
                  onClick={() => startEditing(task)}
                  className="p-2 text-gray-400 hover:text-indigo-600 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 dark:hover:text-indigo-400 rounded-lg transition-colors"
                >
                  <Edit2 className="w-4 h-4" />
                </button>
                <button
                  onClick={() => handleDeleteTask(task.id)}
                  className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/30 dark:hover:text-red-400 rounded-lg transition-colors"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            </div>
          ))
        )}
      </div>

      {/* --- STATS BAR --- */}
      <div className="mt-8 grid grid-cols-3 gap-4">
        <div className="p-4 bg-white/50 dark:bg-gray-800/40 rounded-2xl border border-white/50 dark:border-gray-700/50 text-center backdrop-blur-sm">
           <div className="text-2xl font-bold text-gray-800 dark:text-white">{tasks.length}</div>
           <div className="text-xs text-gray-500 uppercase tracking-wider">Total</div>
        </div>
        <div className="p-4 bg-white/50 dark:bg-gray-800/40 rounded-2xl border border-white/50 dark:border-gray-700/50 text-center backdrop-blur-sm">
           <div className="text-2xl font-bold text-green-500">{tasks.filter(t => t.completed).length}</div>
           <div className="text-xs text-gray-500 uppercase tracking-wider">Done</div>
        </div>
        <div className="p-4 bg-white/50 dark:bg-gray-800/40 rounded-2xl border border-white/50 dark:border-gray-700/50 text-center backdrop-blur-sm">
           <div className="text-2xl font-bold text-indigo-500">{tasks.filter(t => !t.completed).length}</div>
           <div className="text-xs text-gray-500 uppercase tracking-wider">Pending</div>
        </div>
      </div>

    </div>
  );
};

export default TodoList;